const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const sn = j.snippet || {};
  const cd = j.contentDetails || {};
  const videoId = cd.videoId || (sn.resourceId && sn.resourceId.videoId);
  if (!videoId) continue;
  out.push({ json: {
    video_id: videoId,
    title: sn.title || '',
    channel: sn.videoOwnerChannelTitle || sn.channelTitle || '',
    url: 'https://www.youtube.com/watch?v=' + videoId,
    published_at: sn.publishedAt || '',
    added_to_playlist_at: cd.videoPublishedAt || sn.publishedAt || ''
  }});
}
return out;

const cache = $('Cache Existing IDs').first().json;
const existing = new Set(cache.existing_ids || []);
return $input.all().filter(i => !existing.has(i.json.video_id));

// Robust pairing via pairedItem/itemMatching with index-fallback.
const out = [];
const apifyItems = $input.all();
const sourceFallback = $('Filter New').all();
for (let i = 0; i < apifyItems.length; i++) {
  let meta = {};
  try {
    const m = $('Filter New').itemMatching(i);
    if (m && m.json) meta = m.json;
  } catch (e) {
    if (sourceFallback[i] && sourceFallback[i].json) meta = sourceFallback[i].json;
  }
  const raw = apifyItems[i].json;
  let chunks = [];
  if (Array.isArray(raw)) chunks = raw;
  else if (raw && Array.isArray(raw.data)) chunks = raw.data;
  else if (raw && Array.isArray(raw.transcript)) chunks = raw.transcript;
  else if (raw && Array.isArray(raw.body)) chunks = raw.body;
  const text = chunks.map(c => typeof c === 'string' ? c : (c && (c.text || c.transcript || c.snippet) || '')).filter(Boolean).join(' ').trim();
  const status = text.length > 100 ? 'ok' : 'no_transcript';
  out.push({ json: { ...meta, transcript: text, transcript_status: status, transcript_length: text.length } });
}
return out;

const out = [];
const items = $input.all();
const baseSystem = 'Du bist Insight-Extractor fuer YouTube-Videos. Du extrahierst die wichtigsten Key Points.\n\nOUTPUT-REGELN:\n- Markdown-Bullets, 3-7 Stueck, jeder Bullet max 1-2 Zeilen.\n- Scanbar in 30 Sekunden.\n- Antworte in DERSELBEN SPRACHE wie das Video (keine Uebersetzung).\n- Gib NUR die Bullets zurueck, keine Einleitung, kein Schluss-Wrap-Up, keine Code-Fences.\n- KEINE Zusammenfassung - extrahiere den Saft: konkrete Zahlen, Frameworks, Tools, Zitate, Empfehlungen, Daten, neue Ideen.\n- Falls das Video keine echten Insights hat (reines Entertainment, Werbung, Vlog), schreibe genau: (keine relevanten Insights).';
for (const item of items) {
  const j = item.json;
  const userIntro = 'Titel: ' + (j.title || '') + '\nKanal: ' + (j.channel || '') + '\nURL: ' + (j.url || '');
  let geminiBody;
  let mode;
  if (j.transcript_status === 'ok' && j.transcript_length > 100) {
    mode = 'text';
    const text = (j.transcript || '').slice(0, 50000);
    geminiBody = JSON.stringify({
      systemInstruction: { parts: [{ text: baseSystem }] },
      contents: [{ parts: [{ text: userIntro + '\n\nTRANSKRIPT:\n' + text }] }],
      generationConfig: { temperature: 0.3, maxOutputTokens: 1500, thinkingConfig: { thinkingBudget: 0 } }
    });
  } else {
    mode = 'video';
    geminiBody = JSON.stringify({
      systemInstruction: { parts: [{ text: baseSystem }] },
      contents: [{ parts: [ { fileData: { fileUri: j.url } }, { text: userIntro + '\n\nExtrahiere die Key Points aus diesem Video direkt.' } ] }],
      generationConfig: { temperature: 0.3, maxOutputTokens: 1500, thinkingConfig: { thinkingBudget: 0 } }
    });
  }
  out.push({ json: { ...j, gemini_body: geminiBody, gemini_mode: mode } });
}
return out;

// Robust pairing via pairedItem/itemMatching with index-fallback.
const out = [];
const respItems = $input.all();
const sourceFallback = $('Build Gemini Body').all();
for (let i = 0; i < respItems.length; i++) {
  let meta = {};
  try {
    const m = $('Build Gemini Body').itemMatching(i);
    if (m && m.json) meta = m.json;
  } catch (e) {
    if (sourceFallback[i] && sourceFallback[i].json) meta = sourceFallback[i].json;
  }
  const resp = respItems[i].json || {};
  let text = '';
  try {
    if (resp && resp.candidates && resp.candidates[0] && resp.candidates[0].content && resp.candidates[0].content.parts && resp.candidates[0].content.parts[0]) {
      text = (resp.candidates[0].content.parts[0].text || '').trim();
      text = text.replace(/^```\w*\s*/i, '').replace(/\s*```$/, '').trim();
    } else if (resp && resp.error && resp.error.message) {
      text = '(Gemini-Fehler: ' + resp.error.message + ')';
    } else if (resp && resp.promptFeedback && resp.promptFeedback.blockReason) {
      text = '(Gemini-blockiert: ' + resp.promptFeedback.blockReason + ')';
    } else {
      text = '(unerwartete Gemini-Antwort)';
    }
  } catch (e) {
    text = '(Parse-Fehler: ' + (e && e.message || String(e)) + ')';
  }
  out.push({ json: {
    video_id: meta.video_id || '',
    title: meta.title || '',
    channel: meta.channel || '',
    url: meta.url || '',
    published_at: meta.published_at || '',
    added_to_playlist_at: meta.added_to_playlist_at || '',
    language: '',
    transcript_status: meta.transcript_status || 'unknown',
    gemini_mode: meta.gemini_mode || '',
    key_points: text,
    summary_sent_at: ''
  }});
}
return out;

const items = $input.all();
const withInsights = items.filter(i => {
  const kp = (i.json.key_points || '').toLowerCase();
  if (!kp) return false;
  if (/keine relevanten insights/i.test(kp)) return false;
  if (kp.startsWith('(gemini-fehler') || kp.startsWith('(gemini-blockiert') || kp.startsWith('(parse-fehler') || kp.startsWith('(unerwartete gemini')) return false;
  return true;
});
if (withInsights.length === 0) return [];

const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const mdToHtml = md => {
  const lines = String(md).split(/\r?\n/);
  let html = ''; let inList = false;
  for (const line of lines) {
    const m = line.match(/^\s*[-*•]\s+(.*)$/);
    if (m) {
      if (!inList) { html += '<ul style="margin:8px 0 12px 20px;padding:0;">'; inList = true; }
      let c = esc(m[1]);
      c = c.replace(/\*\*([^*]+)\*\*/g, '<strong>' + '$' + '1</strong>');
      c = c.replace(/\*([^*]+)\*/g, '<em>' + '$' + '1</em>');
      html += '<li style="margin-bottom:6px;line-height:1.5;">' + c + '</li>';
    } else {
      if (inList) { html += '</ul>'; inList = false; }
      const t = line.trim();
      if (t) html += '<p style="margin:8px 0;line-height:1.5;">' + esc(t) + '</p>';
    }
  }
  if (inList) html += '</ul>';
  return html;
};

const today = new Date().toLocaleDateString('de-DE', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
const headerLine = withInsights.length === 1 ? '1 neues Video' : withInsights.length + ' neue Videos';
const sheetUrl = 'https://docs.google.com/spreadsheets/d/1EfVBDj8QVgyUkSMGZMsmYTCXWmRh_ri0x4oDHLizOCw';

let body = '<!DOCTYPE html><html><body style="font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;max-width:680px;margin:0 auto;padding:24px;color:#1a1a1a;background:#fafafa;">';
body += '<div style="margin-bottom:24px;"><h1 style="margin:0 0 4px;font-size:22px;color:#111;">AI Video Digest</h1>';
body += '<p style="margin:0;color:#666;font-size:14px;">' + esc(today) + ' · ' + headerLine + ' aus deiner Playlist</p></div>';
for (const it of withInsights) {
  const j = it.json;
  const modeBadge = j.gemini_mode === 'video' ? '<span style="display:inline-block;font-size:10px;background:#fff3cd;color:#856404;padding:2px 6px;border-radius:4px;margin-left:6px;">via Video-Direkt-Analyse</span>' : '';
  body += '<div style="background:#fff;border:1px solid #e5e5e5;border-radius:12px;padding:20px;margin-bottom:16px;">';
  body += '<div style="font-size:12px;color:#888;margin-bottom:4px;">' + esc(j.channel) + modeBadge + '</div>';
  body += '<h2 style="margin:0 0 12px;font-size:17px;line-height:1.3;"><a href="' + esc(j.url) + '" style="color:#111;text-decoration:none;">' + esc(j.title) + '</a></h2>';
  body += '<div style="font-size:14px;color:#222;">' + mdToHtml(j.key_points) + '</div>';
  body += '<div style="margin-top:12px;"><a href="' + esc(j.url) + '" style="display:inline-block;padding:8px 14px;background:#ff0000;color:#fff;border-radius:6px;text-decoration:none;font-size:13px;">Video oeffnen</a></div>';
  body += '</div>';
}
body += '<p style="margin-top:24px;color:#999;font-size:12px;text-align:center;">Automatisiert via n8n + Gemini 2.5 Flash · <a href="' + sheetUrl + '" style="color:#999;">State Sheet</a></p>';
body += '</body></html>';

const subject = withInsights.length === 1 ? 'AI Video Digest — ' + withInsights[0].json.title.slice(0, 60) : 'AI Video Digest — ' + withInsights.length + ' neue Videos';

return [{ json: { subject, body_html: body, video_ids: withInsights.map(i => i.json.video_id), count: withInsights.length } }];

const items = $input.all();
const videoIds = $('Aggregate Email Body').first().json.video_ids || [];
const now = new Date().toISOString();
return videoIds.map(id => ({ json: { video_id: id, summary_sent_at: now } }));
